-- Демо-заказы от демо-заказчиков. Помечены is_demo = TRUE, откликаться нельзя.
INSERT INTO t_p87694549_free_task_finder.jobs
  (owner_id, title, description, price, city, when_text, category, status, moderation,
   is_demo, photo_thumb, photo_full, created_at, bumped_at, expires_at)
SELECT u.id, v.title, v.descr, v.price, v.city, v.when_text, v.category, 'open', 'approved',
       TRUE, v.thumb, v.big, NOW() - (v.age_hours || ' hours')::interval,
       NOW() - (v.age_hours || ' hours')::interval, NOW() + INTERVAL '30 days'
FROM (VALUES
('demo_cu_01','Собрать шкаф-купе','Купили шкаф в Хоффе, привезли в разобранном виде. Нужен человек с инструментом, чтобы собрать. Инструкция есть, все детали на месте. Квартира на 5 этаже, лифт работает.',2500,'Ярославль, Кировский район','В ближайшие дни','Ремонт',5,'/demo/jobs/wardrobe-thumb.jpg','/demo/jobs/wardrobe.jpg'),
('demo_cu_02','Течёт смеситель на кухне','Капает из-под основания смесителя, под мойкой уже лужа. Смеситель старый, наверное проще поменять. Новый куплю сам, скажите какой брать.',1500,'Ярославль, Ленинский район','Срочно','Ремонт',9,'/demo/jobs/faucet-thumb.jpg','/demo/jobs/faucet.jpg'),
('demo_cu_03','Покосить траву на даче','Участок 8 соток, трава по пояс, давно не косили. Нужен человек со своей косой. Электричество на участке есть. Садоводство за Заволжским, доеду покажу.',3000,'Ярославль, Заволжский район','На выходных','Дача и участок',14,'/demo/jobs/grass-thumb.jpg','/demo/jobs/grass.jpg'),
('demo_cu_04','Помочь с переездом','Переезжаем из однушки в двушку, оба дома в Дзержинском. Вещи уже в коробках, есть диван, холодильник и стиралка. Нужны двое крепких, машина своя.',4000,'Ярославль, Дзержинский район','В эти выходные','Переезд и грузы',3,'/demo/jobs/boxes-thumb.jpg','/demo/jobs/boxes.jpg'),
('demo_cu_05','Повесить люстру и поменять розетки','Купили люстру, сами боимся лезть. Ещё две розетки в комнате разболтались, надо переставить. Проводка старая, дом 70-х годов.',2000,'Ярославль, Центр','На неделе','Ремонт',20,'/demo/jobs/wiring-thumb.jpg','/demo/jobs/wiring.jpg'),
('demo_cu_06','Уборка после ремонта','Закончили ремонт в комнате, везде строительная пыль, на полу остатки штукатурки. Комната 18 метров. Нужна тщательная уборка со своими средствами.',3500,'Ярославль, Фрунзенский район','Как получится','Уборка',7,'/demo/jobs/dust-thumb.jpg','/demo/jobs/dust.jpg'),
('demo_cu_07','Вынести старую мебель','Надо вынести из квартиры старый диван и два кресла, поставить у контейнеров. Второй этаж без лифта, но лестница широкая.',1800,'Рыбинск','Завтра','Переезд и грузы',11,NULL,NULL),
('demo_cu_08','Генеральная уборка двухкомнатной','Давно не делали генеральную. Нужно помыть окна, кухню, санузел, протереть всё. Квартира 54 метра, живём вдвоём, животных нет.',4500,'Ярославль, Красноперекопский район','На следующей неделе','Уборка',26,NULL,NULL),
('demo_cu_09','Починить дверной замок','Замок во входной двери стал заедать, ключ проворачивается с трудом. Боюсь однажды не открою. Посмотрите, может смазать надо или менять.',1200,'Тутаев','Срочно','Ремонт',31,NULL,NULL),
('demo_cu_10','Вскопать грядки','Огород на даче, нужно вскопать примерно две сотки под посадку. Земля нормальная, не целина. Лопата есть, но своя лучше.',2500,'Переславль-Залесский','До конца недели','Дача и участок',17,NULL,NULL),
('demo_cu_01','Собрать кухонный гарнитур','Привезли кухню, 6 модулей плюс столешница. Нужен опытный человек, чтобы всё встало ровно. Мойку и варочную тоже надо врезать.',6000,'Ярославль, Кировский район','В течение недели','Ремонт',38,NULL,NULL),
('demo_cu_03','Заменить смеситель в ванной','Старый совсем потёк, ржавчина. Купила новый, лежит в коробке. Нужно снять старый и поставить новый.',1500,'Ярославль, Заволжский район','На днях','Ремонт',44,NULL,NULL),
('demo_cu_05','Повесить карнизы в двух комнатах','Купили карнизы, надо повесить. Стены бетонные, нужен перфоратор. Заодно подскажите на какой высоте лучше.',1600,'Ярославль, Центр','Не срочно','Ремонт',52,NULL,NULL),
('demo_cu_02','Убрать ветки после обрезки','Обрезали яблони на участке, куча веток осталась. Надо порубить и вывезти или сложить в углу. Мешки куплю.',2200,'Ярославль, Ленинский район','На выходных','Дача и участок',29,NULL,NULL),
('demo_cu_07','Помыть окна в квартире','Три окна пластиковых, второй этаж. Давно не мыли, снаружи грязные. Нужны свои средства и стремянка.',2000,'Рыбинск','На неделе','Уборка',35,NULL,NULL)
) AS v(owner_max, title, descr, price, city, when_text, category, age_hours, thumb, big)
JOIN t_p87694549_free_task_finder.users u
  ON u.max_id = v.owner_max AND u.role = 'customer' AND u.is_demo = TRUE;